function setSession(s){session=s;s?sessionStorage.setItem("kz_session",JSON.stringify(s)):sessionStorage.removeItem("kz_session")}
function setDbStatus(ok,msg){if($("#dbDot"))$("#dbDot").style.background=ok?"#22C55E":ok===null?"#E8971E":"#EF4444";if($("#dbLabel"))$("#dbLabel").textContent=msg}
function fmtDate(iso){if(!iso)return"—";return new Date(iso).toLocaleDateString(LANG==="ar"?"ar-EG":"en-GB",{day:"numeric",month:"short",year:"numeric"})}
function fmtTime(iso){return new Date(iso).toLocaleTimeString(LANG==="ar"?"ar-EG":"en-GB",{hour:"2-digit",minute:"2-digit"})}
function fmtFull(iso){return fmtDate(iso)+" • "+fmtTime(iso)}
function empById(id){return EMPLOYEES.find(e=>e.id===id)}function empName(id){return empById(id)?.name||"—"}function taskDay(x){return x.due_date||x.created_at?.slice(0,10)}function isToday(x){return x&&x.slice(0,10)===todayStr()}
const PRIOS=["low","medium","high","urgent"],STATUSES=["waiting","in_progress","completed","delayed","cancelled"],CALL_STATUSES=["notCalled","answered","noAnswer","busy","invalidNumber","wrongNumber","callBackLater"],EMAIL_STATUSES=["notSent","sent","invalidEmail"];
const prioBadge=p=>`<span class="badge p-${p}"><span class="dot"></span>${t(p)}</span>`;const statBadge=s=>`<span class="badge b-${s}"><span class="dot"></span>${t("s_"+s)}</span>`;

async function loadAllData(){setDbStatus(null,t("initDb"));const [e,d,ta,h,se,sr,fl]=await Promise.all([sb.from("employees").select("*").eq("active",true).order("created_at"),sb.from("departments").select("*").order("created_at"),sb.from("tasks").select("*").order("created_at",{ascending:false}),sb.from("task_history").select("*").order("created_at",{ascending:false}).limit(200),sb.from("settings").select("*").eq("id",1).single(),sb.from("sales_reports").select("*").order("created_at",{ascending:false}).then(r=>r).catch(()=>({data:[]})),sb.from("sales_followups").select("*").order("created_at",{ascending:false}).then(r=>r).catch(()=>({data:[]}))]);
if(e.error){setDbStatus(false,t("dbError"));showSqlHelp();return false}EMPLOYEES=e.data||[];DEPARTMENTS=d.data||[];TASKS=ta.data||[];HISTORY=h.data||[];SR_CACHE=sr.data||[];FOLLOWUPS_CACHE=fl.data||[];if(se.data)SETTINGS={password:se.data.password,company:se.data.company,companyAr:se.data.company_ar,seq:se.data.seq||0,defaultDept:se.data.default_dept||"Sales"};setDbStatus(true,t("dbConnected"));return true}
function showSqlHelp(){openModal(`<h3>Database Setup<button class="x" onclick="closeModal()">${IC.xmark}</button></h3><p style="color:var(--muted);line-height:1.7">Run setup.sql and update_employees.sql in Supabase SQL Editor, then reload.</p>`,460)}
function setupRealtime(){sb.channel("kaizen-rt").on("postgres_changes",{event:"*",schema:"public",table:"tasks"},async()=>{const r=await sb.from("tasks").select("*").order("created_at",{ascending:false});TASKS=r.data||[];rerenderCurrent()}).on("postgres_changes",{event:"*",schema:"public",table:"sales_followups"},async()=>{const r=await sb.from("sales_followups").select("*").order("created_at",{ascending:false});FOLLOWUPS_CACHE=r.data||[];rerenderCurrent()}).on("postgres_changes",{event:"INSERT",schema:"public",table:"notifications"},async p=>{if(session?.role==="admin"&&p.new.emp_id===null)toast(p.new.title,"i");if(session?.role==="employee"&&p.new.emp_id===session.empId)toast(p.new.title,"i")}).subscribe()}
async function nextTaskId(){SETTINGS.seq=(SETTINGS.seq||0)+1;await sb.from("settings").update({seq:SETTINGS.seq}).eq("id",1);return"KT-"+String(SETTINGS.seq).padStart(4,"0")}
async function addHistory(task_id,action,extra=""){const actor=session?(session.role==="admin"?"Admin":empName(session.empId)):"System";await sb.from("task_history").insert({task_id,action,extra,actor});HISTORY.unshift({task_id,action,extra,actor,created_at:nowISO()})}
async function notifyEmp(emp_id,title){if(emp_id)await sb.from("notifications").insert({emp_id,title,read:false})}

function toast(msg,type="s"){const icons={s:IC.check,e:IC.xmark,w:IC.bolt,i:IC.bolt};const el=document.createElement("div");el.className="toast "+type;el.innerHTML=`<div class="ti">${icons[type]}</div><div>${esc(msg)}</div>`;$("#toasts").appendChild(el);setTimeout(()=>{el.style.opacity="0";el.style.transform="translateY(10px)";setTimeout(()=>el.remove(),300)},3200)}
function openModal(html,maxW){$("#modalRoot").innerHTML=`<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" ${maxW?`style="max-width:${maxW}px"`:""}>${html}</div></div>`}function closeModal(){$("#modalRoot").innerHTML=""}function confirmModal(msg,yes,danger=true){openModal(`<h3>${t("confirm")}<button class="x" onclick="closeModal()">${IC.xmark}</button></h3><p style="color:var(--muted);margin-bottom:22px">${esc(msg)}</p><div style="display:flex;gap:10px;justify-content:flex-end"><button class="btn btn-outline" onclick="closeModal()">${t("cancel")}</button><button id="yesBtn" class="btn ${danger?"btn-danger":"btn-primary"}">${t("confirm")}</button></div>`,430);$("#yesBtn").onclick=()=>{closeModal();yes()}}
document.addEventListener("click",e=>{const b=e.target.closest(".btn,.login-btn");if(!b)return;const r=b.getBoundingClientRect(),s=document.createElement("span"),z=Math.max(r.width,r.height);s.className="ripple";s.style.cssText=`width:${z}px;height:${z}px;left:${e.clientX-r.left-z/2}px;top:${e.clientY-r.top-z/2}px`;b.appendChild(s);setTimeout(()=>s.remove(),600)});

function render(){if(!session){renderLogin();$("#appView").classList.remove("on");$("#loginView").style.display="flex";return}$("#loginView").style.display="none";$("#appView").classList.add("on");renderSidebar();renderTopbar();renderContent()}
function rerenderCurrent(){if(session)renderContent()}
function renderLogin(){let inner="";if(loginStep==="root")inner=`<div class="brand-logo"><img src="${LOGO_URL}"></div><h1>${t("loginTitle")}</h1><div class="sub">${t("loginSub")}</div><button class="login-btn btn-blue" onclick="loginStep='emp';renderLogin()">${IC.users}${t("loginEmp")}</button><button class="login-btn btn-ghost" onclick="loginStep='admin';renderLogin()">${IC.gear}${t("loginAdmin")}</button><button class="lang-pill" onclick="switchLang()">${IC.globe} ${LANG==="ar"?"English":"العربية"}</button>`;else if(loginStep==="emp")inner=`<span class="back-link" onclick="loginStep='root';renderLogin()">‹ ${t("back")}</span><div class="brand-logo"><img src="${LOGO_URL}"></div><h1>${t("loginEmp")}</h1><div class="sub">${t("chooseName")}</div><select id="empSel"><option value="">${t("chooseName")}</option>${EMPLOYEES.map(e=>`<option value="${e.id}">${esc(e.name)} — ${esc(e.department)}</option>`).join("")}</select><button class="login-btn btn-blue" style="margin-top:16px" onclick="empLogin()">${t("enter")}</button>`;else inner=`<span class="back-link" onclick="loginStep='root';renderLogin()">‹ ${t("back")}</span><div class="brand-logo"><img src="${LOGO_URL}"></div><h1>${t("loginAdmin")}</h1><div class="sub">${t("adminPass")}</div><input id="adminPass" type="password" placeholder="••••" onkeydown="if(event.key==='Enter')adminLogin()"><button class="login-btn btn-blue" style="margin-top:16px" onclick="adminLogin()">${t("enter")}</button>`;$("#loginView").innerHTML=`<div class="login-card">${inner}</div>`}
function empLogin(){const id=$("#empSel").value;if(!id)return toast(t("fillRequired"),"w");setSession({role:"employee",empId:id});currentView="empHome";render()}function adminLogin(){if($("#adminPass").value===SETTINGS.password){setSession({role:"admin"});currentView="dashboard";render()}else toast(t("wrongPass"),"e")}function logout(){setSession(null);currentView="dashboard";render()}function switchLang(){LANG=LANG==="ar"?"en":"ar";localStorage.setItem("kz_lang",LANG);document.documentElement.lang=LANG;document.documentElement.dir=LANG==="ar"?"rtl":"ltr";render()}
function isSalesEmp(){return empById(session?.empId)?.department==="Sales"}function nav(v){currentView=v;toggleSide(false);render()}function toggleSide(open){$("#sidebar")?.classList.toggle("open",open);$("#sideOverlay")?.classList.toggle("on",open)}
function renderSidebar(){let items=session.role==="admin"?[["dashboard",IC.dash,"dashboard"],["create",IC.plus,"createTask"],["tasks",IC.tasks,"tasks"],["board",IC.board,"planBoard"],["employees",IC.users,"employees"],["reports",IC.chart,"reports"],["salesReports",IC.chart,"salesReports"],["archive",IC.archive,"archive"],["settings",IC.gear,"settings"]]:[["empHome",IC.dash,"todayTasks"]];if(session.role==="employee"&&isSalesEmp())items.push(["empCreate",IC.plus,"salesCreateTask"],["salesReport",IC.chart,"salesReports"]);$("#sidebar").innerHTML=`<div class="side-head"><div class="side-logo"><img src="${LOGO_URL}"></div><div><b>${esc(SETTINGS.company)}</b><span>${esc(LANG==="ar"?SETTINGS.companyAr:"Kaizen Adv. Agency")}</span></div></div><nav class="side-nav">${items.map(([v,ic,l])=>`<button class="nav-item ${currentView===v?"active":""}" onclick="nav('${v}')">${ic}<span>${t(l)}</span></button>`).join("")}</nav><div class="side-foot"><button class="logout-btn" onclick="logout()">${IC.out}<span>${t("logout")}</span></button></div>`}
function renderTopbar(){$("#topbar").innerHTML=`<button class="icon-btn menu-btn" onclick="toggleSide(true)">${IC.menu}</button><div class="top-date"><b id="tbDate"></b><span id="tbTime"></span></div><div class="search-wrap">${IC.search}<input id="topSearch" placeholder="${t("search")}" value="${esc(topSearch)}"></div><button class="lang-pill" style="margin:0" onclick="switchLang()">${IC.globe} ${LANG==="ar"?"English":"العربية"}</button><button class="icon-btn" onclick="logout()">${IC.out}</button>`;tickClock();$("#topSearch").oninput=e=>{topSearch=e.target.value;if(session.role==="admin"&&topSearch.trim())currentView="tasks";renderSidebar();renderContent()}}
let clockTimer;function tickClock(){const d=new Date();if($("#tbDate"))$("#tbDate").textContent=d.toLocaleDateString(LANG==="ar"?"ar-EG":"en-GB",{weekday:"long",day:"numeric",month:"long",year:"numeric"});if($("#tbTime"))$("#tbTime").textContent=d.toLocaleTimeString(LANG==="ar"?"ar-EG":"en-GB");clearTimeout(clockTimer);clockTimer=setTimeout(tickClock,1000)}
async function renderContent(){const c=$("#content");if(session.role==="employee"){if(currentView==="empCreate"){salesCreateTaskModal();currentView="empHome"}c.innerHTML=currentView==="salesReport"?await viewSalesReport():viewEmpHome();return}if(currentView==="salesReports"){c.innerHTML=await viewAdminSalesReports();return}const views={dashboard:viewDashboard,create:viewCreate,tasks:viewTasks,board:viewBoard,employees:viewEmployees,reports:viewReports,archive:viewArchive,settings:viewSettings};c.innerHTML=(views[currentView]||viewDashboard)();if(currentView==="create")filterEmpByDept();if(currentView==="board")bindBoardDnD();if(currentView==="tasks"&&tasksViewMode==="kanban")bindKanbanDnD()}

function viewDashboard(){const live=TASKS.filter(x=>!x.archived),today=live.filter(x=>taskDay(x)===todayStr()),prod=today.length?Math.round(today.filter(x=>x.status==="completed").length/today.length*100):0;const cards=[["totalTasks",live.length,IC.tasks,"#1B3A5C"],["doneToday",live.filter(x=>x.status==="completed"&&isToday(x.completed_at)).length,IC.check,"#22C55E"],["inProgress",live.filter(x=>x.status==="in_progress").length,IC.pulse,"#2A5082"],["waiting",live.filter(x=>x.status==="waiting").length,IC.tasks,"#5A7A9B"],["delayed",live.filter(x=>x.status==="delayed").length,IC.bolt,"#E8971E"],["cancelled",live.filter(x=>x.status==="cancelled").length,IC.xmark,"#EF4444"],["productivity",prod+"%",IC.trend,"#22C55E"]];const depts=DEPARTMENTS.map(d=>({n:d.name,c:live.filter(x=>x.department===d.name).length})).filter(x=>x.c);return`<h1 class="page-title anim-up">${t("overview")}</h1><div class="page-sub anim-up">${fmtDate(nowISO())}</div><div class="grid stats-grid">${cards.map(([k,v,ic,col],i)=>`<div class="stat-card card" style="animation-delay:${i*50}ms"><div class="row1"><span class="label">${t(k)}</span><span class="stat-ic" style="background:${col}1a;color:${col}">${ic}</span></div><div class="num">${v}</div></div>`).join("")}</div><div class="grid dash-grid"><div class="card" style="padding:24px"><b>${t("byDept")}</b><div style="margin-top:18px">${depts.map((x,i)=>`<div class="hbar-row"><span class="lb">${esc(x.n)}</span><span class="tr"><i style="width:${Math.min(100,x.c*20)}%;background:#E8971E"></i></span><span class="vl">${x.c}</span></div>`).join("")||`<div class="empty">${t("noResults")}</div>`}</div></div><div class="card" style="padding:24px"><b>${t("recentActivity")}</b><div class="timeline" style="margin-top:18px">${HISTORY.slice(0,8).map(h=>`<div class="tl-item"><div>${esc(h.action)} — <span class="tid">${h.task_id}</span></div><div class="ts">${esc(h.actor||"")} • ${fmtFull(h.created_at)}</div></div>`).join("")||`<div class="empty">${t("noResults")}</div>`}</div></div></div>`}
function viewCreate(){
  return`<h1 class="page-title anim-up">${t("createTask")}</h1><div class="card anim-up" style="padding:30px;max-width:900px"><div class="form-grid"><div><label>${t("customer")}</label><input id="fCust"></div><div><label>${t("department")} *</label><select id="fDept" onchange="filterEmpByDept()"><option value="">${t("chooseDept")}</option>${DEPARTMENTS.map(d=>`<option ${d.name===SETTINGS.defaultDept?"selected":""}>${esc(d.name)}</option>`).join("")}</select></div><div><label>${t("employee")} *</label><select id="fEmp"></select></div><div><label>${t("priority")}</label><div class="prio-group" id="prioGroup">${PRIOS.map(p=>`<button type="button" data-prio="${p}" class="prio-chip ${p===createPrio?"sel-"+p:""}" onclick="selectPriority('${p}')">${t(p)}</button>`).join("")}</div></div><div><label>${t("dueDate")}</label><input id="fDue" type="date" value="${todayStr()}"></div><div class="full"><label>${t("description")} *</label><textarea id="fDesc" rows="4"></textarea></div><div class="full"><label>${t("notes")}</label><textarea id="fNotes" rows="3"></textarea></div></div><div style="display:flex;gap:12px;margin-top:26px"><button class="btn btn-primary" onclick="createTask()">${IC.plus} ${t("create")}</button><button class="btn btn-outline" onclick="resetCreateForm()">${t("reset")}</button></div></div>`
}
window.selectPriority = function(p){
  createPrio = p;
  document.querySelectorAll("#prioGroup .prio-chip").forEach(btn=>{
    btn.className = "prio-chip" + (btn.dataset.prio===p ? " sel-"+p : "");
  });
}
window.resetCreateForm = function(){
  createPrio = "medium";
  renderContent();
}
function filterEmpByDept(){const d=$("#fDept")?.value,sel=$("#fEmp");if(!sel)return;sel.innerHTML=`<option value="">${t("chooseEmp")}</option>`+EMPLOYEES.filter(e=>!d||e.department===d).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join("")}
async function createTask(){const cust=$("#fCust").value.trim()||"—",dept=$("#fDept").value,emp=$("#fEmp").value,desc=$("#fDesc").value.trim(),due=$("#fDue").value,notes=$("#fNotes").value.trim();if(!dept||!emp||!desc)return toast(t("fillRequired"),"w");const tid=await nextTaskId(),task={task_id:tid,customer_name:cust,department:dept,employee_id:emp,description:desc,quantity:1,priority:createPrio,status:"waiting",notes,due_date:due||todayStr(),created_by:"Admin"};const r=await sb.from("tasks").insert(task);if(r.error)return toast(r.error.message,"e");TASKS.unshift({...task,created_at:nowISO(),updated_at:nowISO(),archived:false});await addHistory(tid,"actCreated");await notifyEmp(emp,t("taskCreated")+" • "+tid);toast(t("taskCreated"),"s");renderContent()}
function filteredTasks(){let list=TASKS.filter(x=>!x.archived);const q=topSearch.toLowerCase();if(q)list=list.filter(x=>[x.task_id,x.customer_name,x.department,empName(x.employee_id),x.description].join(" ").toLowerCase().includes(q));if(taskFilter!=="all")list=list.filter(x=>x.status===taskFilter||taskFilter==="today"&&taskDay(x)===todayStr());return list}
function viewTasks(){const list=filteredTasks();return`<div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><h1 class="page-title">${t("tasks")}</h1><div class="seg"><button class="${tasksViewMode==="table"?"on":""}" onclick="tasksViewMode='table';renderContent()">Table</button><button class="${tasksViewMode==="kanban"?"on":""}" onclick="tasksViewMode='kanban';renderContent()">Kanban</button></div></div><div class="chips">${[["all","all"],["today","today"],["waiting","s_waiting"],["in_progress","s_in_progress"],["completed","s_completed"],["delayed","s_delayed"],["cancelled","s_cancelled"]].map(([k,l])=>`<button class="chip ${taskFilter===k?"on":""}" onclick="taskFilter='${k}';renderContent()">${t(l)}</button>`).join("")}</div>${tasksViewMode==="kanban"?renderKanban(list):renderTaskTable(list)}`}
function renderTaskTable(list){return`<div class="card table-wrap"><table><thead><tr><th>${t("taskId")}</th><th>${t("customer")}</th><th>${t("department")}</th><th>${t("employee")}</th><th>${t("priority")}</th><th>${t("status")}</th><th>${t("createdAt")}</th><th>${t("actions")}</th></tr></thead><tbody>${list.map(x=>`<tr><td><span class="tid" onclick="openTaskDetails('${x.task_id}')">${x.task_id}</span></td><td>${esc(x.customer_name)}</td><td>${esc(x.department)}</td><td>${esc(empName(x.employee_id))}</td><td>${prioBadge(x.priority)}</td><td>${statBadge(x.status)}</td><td>${fmtDate(x.created_at)}</td><td><div class="row-actions"><button class="act" onclick="openTaskDetails('${x.task_id}')">${IC.eye}</button><button class="act" onclick="changeStatus('${x.task_id}','completed')">${IC.check}</button><button class="act danger" onclick="deleteTask('${x.task_id}')">${IC.trash}</button></div></td></tr>`).join("")||`<tr><td colspan="8"><div class="empty">${t("noResults")}</div></td></tr>`}</tbody></table></div>`}
function renderKanban(list){return`<div class="kanban">${STATUSES.map(s=>`<div class="kcol" data-status="${s}"><div class="kcol-head">${t("s_"+s)}<span class="cnt">${list.filter(x=>x.status===s).length}</span></div><div class="kcol-body">${list.filter(x=>x.status===s).map(x=>`<div class="kitem" draggable="true" data-tid="${x.task_id}"><div class="tid">${x.task_id}</div><b>${esc(x.customer_name)}</b><div style="color:var(--muted);font-size:13px">${esc(x.description)}</div></div>`).join("")}</div></div>`).join("")}</div>`}
function bindKanbanDnD(){let tid=null;document.querySelectorAll(".kitem").forEach(e=>{e.ondragstart=()=>{tid=e.dataset.tid;e.classList.add("dragging")};e.ondragend=()=>e.classList.remove("dragging")});document.querySelectorAll(".kcol").forEach(c=>{c.ondragover=e=>{e.preventDefault();c.classList.add("dragover")};c.ondragleave=()=>c.classList.remove("dragover");c.ondrop=e=>{e.preventDefault();c.classList.remove("dragover");if(tid)changeStatus(tid,c.dataset.status)}})}
async function changeStatus(tid,status){const x=TASKS.find(x=>x.task_id===tid);if(!x)return;const upd={status,updated_at:nowISO(),completed_at:status==="completed"?nowISO():null};const r=await sb.from("tasks").update(upd).eq("task_id",tid);if(r.error)return toast(r.error.message,"e");Object.assign(x,upd);await addHistory(tid,status==="completed"?"actCompleted":"actStatus",status);toast(t("taskUpdated"),"s");rerenderCurrent()}
function deleteTask(tid){confirmModal(t("delete")+"?",async()=>{await sb.from("tasks").delete().eq("task_id",tid);TASKS=TASKS.filter(x=>x.task_id!==tid);toast(t("taskDeleted"),"s");rerenderCurrent()})}
async function openTaskDetails(tid){const x=TASKS.find(x=>x.task_id===tid);if(!x)return;const h=await sb.from("task_history").select("*").eq("task_id",tid).order("created_at",{ascending:false});openModal(`<h3>${t("details")} <button class="x" onclick="closeModal()">${IC.xmark}</button></h3><div class="detail-grid"><div class="dg"><div class="k">${t("taskId")}</div><div class="v">${x.task_id}</div></div><div class="dg"><div class="k">${t("status")}</div><div class="v">${statBadge(x.status)}</div></div><div class="dg"><div class="k">${t("customer")}</div><div class="v">${esc(x.customer_name)}</div></div><div class="dg"><div class="k">${t("employee")}</div><div class="v">${esc(empName(x.employee_id))}</div></div><div class="dg full"><div class="k">${t("description")}</div><div class="v">${esc(x.description)}</div></div>${x.feedback?`<div class="dg full"><div class="k">${t("feedback")}</div><div class="v">${esc(x.feedback)}</div></div>`:""}</div><div class="timeline">${(h.data||[]).map(i=>`<div class="tl-item"><div>${esc(i.action)}</div><div class="ts">${esc(i.actor||"")} • ${fmtFull(i.created_at)}</div></div>`).join("")}</div>`,620)}
function todayBoardTasks(){return TASKS.filter(x=>!x.archived&&taskDay(x)===todayStr())}
function viewBoard(){const tasks=todayBoardTasks();return`<div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><h1 class="page-title">${t("planBoard")}</h1><button class="btn btn-outline btn-sm" onclick="downloadDailyPdf()">${IC.archive} ${t("downloadPdf")}</button></div><div class="board">${EMPLOYEES.map(e=>{const mine=tasks.filter(x=>x.employee_id===e.id);return`<div class="bcol" data-emp="${e.id}"><div class="bcol-head"><div class="avatar">${esc(e.name[0])}</div><div><b>${esc(e.name)}</b><div style="color:var(--muted);font-size:12px">${esc(e.department)}</div></div><span class="cnt">${mine.length}</span></div><div class="bcol-body">${mine.map(x=>`<div class="bitem ${x.status==="completed"?"done":""}" draggable="true" data-tid="${x.task_id}"><div><span class="chk" onclick="changeStatus('${x.task_id}','completed')">${x.status==="completed"?"✓":""}</span> <span class="txt">${esc(x.description)}</span></div><div style="font-size:12px;color:var(--muted)">${esc(x.customer_name)}</div></div>`).join("")}</div></div>`}).join("")}</div>`}
function bindBoardDnD(){let tid=null;document.querySelectorAll(".bitem").forEach(e=>{e.ondragstart=()=>tid=e.dataset.tid});document.querySelectorAll(".bcol").forEach(c=>{c.ondragover=e=>e.preventDefault();c.ondrop=async()=>{const x=TASKS.find(x=>x.task_id===tid),em=empById(c.dataset.emp);if(x&&em){await sb.from("tasks").update({employee_id:em.id,department:em.department}).eq("task_id",tid);x.employee_id=em.id;x.department=em.department;rerenderCurrent()}}})}
function followupResultBadge(result){
  const map={positive:["🟢","b-completed"],followup:["🟡","b-delayed"],negative:["🔴","b-cancelled"],no_answer:["⚫","b-waiting"]};
  const m=map[result||"followup"]||map.followup;
  return `<span class="badge ${m[1]}">${m[0]} ${t("fr_"+(result||"followup"))}</span>`;
}
function openEmpProfile(id){
  const e=empById(id);if(!e)return;
  const isSales=e.department==="Sales";
  const all=TASKS.filter(x=>x.employee_id===id);
  const done=all.filter(x=>x.status==="completed").length;
  const rate=all.length?Math.round(done/all.length*100):0;
  
  let salesProfileHtml="";
  if(isSales){
    const fToday=FOLLOWUPS_CACHE.filter(f=>f.employee_id===id&&f.created_at.slice(0,10)===todayStr());
    const pct=Math.min(100,Math.round((fToday.length/50)*100));
    
    salesProfileHtml=`<b style="display:block;margin-top:20px;margin-bottom:12px;font-size:16px">${t("clientFollowup")} (${t("today")})</b>
    <div style="background:rgba(232,151,30,.04);border:1.5px solid rgba(232,151,30,.15);border-radius:12px;padding:14px;margin-bottom:18px">
      <div class="pbar-row"><span style="font-weight:600">${t("todayFollowups")}</span><span style="font-weight:bold;color:var(--gold-dark)">${fToday.length} / 50 (${pct}%)</span></div>
      <div class="pbar" style="background:rgba(232,151,30,.1);margin-top:6px"><i style="width:${pct}%;background:var(--gold)"></i></div>
    </div>
    <b style="display:block;margin-bottom:12px;font-size:15px">${t("followupLog")} (${t("today")})</b>
    <div class="table-wrap" style="max-height:220px;overflow-y:auto;border:1px solid rgba(27,58,92,.08)">
      <table style="font-size:13px">
        <thead><tr><th>${t("customer")}</th><th>${t("phone")}</th><th>${t("email")}</th><th>${t("callDone")}</th><th>${t("emailSentF")}</th><th>${t("followupResult")}</th><th>${t("createdAt")}</th></tr></thead>
        <tbody>
          ${fToday.map(f=>`<tr>
            <td style="font-weight:600">${esc(f.customer_name)}</td>
            <td style="direction:ltr">${esc(f.phone||"—")}</td>
            <td style="direction:ltr;font-size:12px">${esc(f.email||"—")}</td>
            <td>${f.call_done?`✓ ${t("yes")}`:`— ${t("no")}`}</td>
            <td>${f.email_sent?`✓ ${t("yes")}`:`— ${t("no")}`}</td><td>${followupResultBadge(f.result)}</td>
            <td style="color:var(--muted);font-size:12px">${fmtTime(f.created_at)}</td>
          </tr>`).join("")||`<tr><td colspan="7" style="text-align:center;padding:12px;color:var(--dim)">${t("noFollowups")}</td></tr>`}
        </tbody>
      </table>
    </div>`;
  }

  openModal(`<h3>${t("empProfile")} — ${esc(e.name)}<button class="x" onclick="closeModal()">${IC.xmark}</button></h3>
  <div style="display:flex;align-items:center;gap:14px;margin-bottom:18px">
    <div class="avatar">${esc(e.name[0])}</div>
    <div><b>${esc(e.name)}</b><div style="color:var(--muted);font-size:13px">${esc(e.department)}</div></div>
  </div>
  <div class="detail-grid">
    <div class="dg"><div class="k">${t("total")} Tasks</div><div class="v">${all.length}</div></div>
    <div class="dg"><div class="k">${t("s_completed")} Tasks</div><div class="v" style="color:var(--success)">${done}</div></div>
    <div class="dg full">
      <div class="pbar-row"><span>${t("completion")}</span><span>${rate}%</span></div>
      <div class="pbar"><i style="width:${rate}%"></i></div>
    </div>
  </div>
  ${salesProfileHtml}`,540);
}

function viewEmployees(){return`<h1 class="page-title">${t("employees")}</h1><div class="grid emp-grid">${EMPLOYEES.map(e=>{
  const all=TASKS.filter(x=>x.employee_id===e.id),done=all.filter(x=>x.status==="completed").length,rate=all.length?Math.round(done/all.length*100):0;
  const isSales=e.department==="Sales";
  let salesHtml="";
  if(isSales){
    const fToday=FOLLOWUPS_CACHE.filter(f=>f.employee_id===e.id&&f.created_at.slice(0,10)===todayStr());
    const pct=Math.min(100,Math.round((fToday.length/50)*100));
    salesHtml=`<div style="margin-top:12px;padding-top:12px;border-top:1px dashed rgba(27,58,92,.08)">
      <div class="pbar-row"><span>${t("clientFollowup")} ${t("today")}</span><span style="font-weight:bold;color:var(--gold-dark)">${fToday.length} / 50 (${pct}%)</span></div>
      <div class="pbar" style="background:rgba(232,151,30,.1)"><i style="width:${pct}%;background:var(--gold)"></i></div>
    </div>`;
  }
  return`<div class="card emp-card" onclick="openEmpProfile('${e.id}')"><div class="emp-top"><div class="avatar">${esc(e.name[0])}</div><div><b>${esc(e.name)}</b><div style="color:var(--muted)">${esc(e.department)}</div></div></div><div class="emp-nums"><div><div class="n">${all.length}</div><div class="l">TOTAL</div></div><div><div class="n" style="color:var(--success)">${done}</div><div class="l">DONE</div></div></div><div class="pbar-row"><span>${t("completion")}</span><span>${rate}%</span></div><div class="pbar"><i style="width:${rate}%"></i></div>${salesHtml}</div>`}).join("")}</div>`}
function viewReports(){return`<h1 class="page-title">${t("reports")}</h1><button class="btn btn-primary btn-sm" onclick="downloadReportPdf()">${t("downloadPdf")}</button>${renderTaskTable(TASKS.filter(x=>!x.archived))}`}
function viewArchive(){return`<h1 class="page-title">${t("archive")}</h1>${renderTaskTable(TASKS.filter(x=>x.archived))}`}
function viewSettings(){return`<h1 class="page-title">${t("settings")}</h1><div class="card" style="padding:26px;max-width:680px"><label>${t("companyName")}</label><input id="setCo" value="${esc(SETTINGS.company)}"><label style="margin-top:14px">${t("companyNameAr")}</label><input id="setCoAr" value="${esc(SETTINGS.companyAr)}"><label style="margin-top:14px">${t("newPass")}</label><input id="setPass" type="password"><button class="btn btn-primary" style="margin-top:18px" onclick="saveSettings()">${t("save")}</button></div>`}
async function saveSettings(){SETTINGS.company=$("#setCo").value.trim()||SETTINGS.company;SETTINGS.companyAr=$("#setCoAr").value.trim()||SETTINGS.companyAr;const p=$("#setPass").value.trim();const upd={company:SETTINGS.company,company_ar:SETTINGS.companyAr};if(p){upd.password=p;SETTINGS.password=p}await sb.from("settings").update(upd).eq("id",1);toast(t("dataSaved"),"s");renderSidebar()}
function viewEmpHome(){
  const me=empById(session.empId),mine=TASKS.filter(x=>!x.archived&&x.employee_id===session.empId&&taskDay(x)===todayStr()&&x.status!=="cancelled"),done=mine.filter(x=>x.status==="completed").length,pct=mine.length?Math.round(done/mine.length*100):0,circ=2*Math.PI*44;
  let followupHtml="";
  if(isSalesEmp()){
    const selDate=followupFilterDate||todayStr();
    const mAll=FOLLOWUPS_CACHE.filter(f=>f.employee_id===session.empId);
    const mToday=mAll.filter(f=>f.created_at.slice(0,10)===todayStr());
    const mFil=mAll.filter(f=>f.created_at.slice(0,10)===selDate);
    const cnt=mToday.length,tgt=50,fpct=Math.min(100,Math.round((cnt/tgt)*100));
    followupHtml=`<div style="margin-top:34px;padding-top:24px;border-top:2px dashed rgba(27,58,92,.1)">
      <h2 style="font-size:22px;font-weight:800;margin-bottom:16px;color:var(--navy)">${t("clientFollowup")}</h2>
      <div class="grid stats-grid" style="grid-template-columns:repeat(2,1fr)">
        <div class="stat-card card">
          <div class="row1"><span class="label">${t("todayFollowups")}</span><span class="stat-ic" style="background:rgba(232,151,30,.1);color:var(--gold)">${IC.trend}</span></div>
          <div class="num" style="font-size:32px">${cnt} <span style="font-size:18px;color:var(--muted)">/ ${tgt}</span></div>
        </div>
        <div class="stat-card card">
          <div class="row1"><span class="label">${t("completion")}</span><span class="stat-ic" style="background:rgba(34,197,94,.1);color:var(--success)">${IC.check}</span></div>
          <div class="num">${fpct}%</div>
        </div>
      </div>
      <div class="card" style="padding:16px;margin-bottom:18px;display:flex;align-items:end;gap:14px;flex-wrap:wrap">
        <div style="min-width:210px"><label>${t("filterDate")}</label><input type="date" value="${selDate}" onchange="setFollowupFilterDate(this.value)"></div>
        <button class="btn btn-primary" onclick="openAddFollowupModal()">${IC.plus} ${t("addFollowup")}</button>
      </div>
      <b style="display:block;margin-bottom:12px;font-size:16px">${t("followupLog")} (${fmtDate(selDate)})</b>
      <div class="card table-wrap anim-up">
        <table style="min-width:600px">
          <thead><tr><th>${t("customer")}</th><th>${t("phone")}</th><th>${t("email")}</th><th>${t("callDone")}</th><th>${t("emailSentF")}</th><th>${t("followupResult")}</th><th>${t("createdAt")}</th></tr></thead>
          <tbody>${mFil.length?mFil.map(f=>`<tr><td style="font-weight:600">${esc(f.customer_name)}</td><td style="direction:ltr;text-align:left">${esc(f.phone||"—")}</td><td style="direction:ltr;text-align:left;font-size:13px">${esc(f.email||"—")}</td><td>${f.call_done?`<span class="badge b-completed">✓ ${t("yes")}</span>`:`<span class="badge b-waiting">${t("no")}</span>`}</td><td>${f.email_sent?`<span class="badge b-completed">✓ ${t("yes")}</span>`:`<span class="badge b-waiting">${t("no")}</span>`}</td><td>${followupResultBadge(f.result)}</td><td style="color:var(--muted);font-size:13px">${fmtTime(f.created_at)}</td></tr>`).join(""):`<tr><td colspan="7"><div class="empty">${t("noFollowups")}</div></td></tr>`}</tbody>
        </table>
      </div>
    </div>`;
  }
  
  const heroHtml = `<div class="today-hero"><div class="ring"><svg width="104" height="104"><circle cx="52" cy="52" r="44" fill="none" stroke="rgba(27,58,92,.1)" stroke-width="9"/><circle cx="52" cy="52" r="44" fill="none" stroke="#E8971E" stroke-width="9" stroke-linecap="round" stroke-dasharray="${circ}" stroke-dashoffset="${circ*(1-pct/100)}"/></svg><span class="pct">${pct}%</span></div><div><div style="font-size:24px;font-weight:800">${(new Date().getHours()<12?t("goodMorning"):t("goodEvening"))}${LANG==="ar"?"، ":", "}${esc(me.name)}</div><div style="color:var(--muted)">${esc(me.department)}</div><div style="display:flex;gap:24px;margin-top:14px"><b>${mine.length} ${t("todayTasks")}</b><b style="color:var(--success)">${done} ${t("completedT")}</b><b style="color:var(--warning)">${mine.length-done} ${t("remaining")}</b></div></div></div>`;
  const salesCreateHtml = isSalesEmp()?`<div class="card" style="padding:18px;margin-bottom:20px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><b>${t("salesCreateTask")}</b><div style="color:var(--muted);font-size:13px">${t("salesCanCreate")}</div></div><button class="btn btn-primary btn-sm" onclick="salesCreateTaskModal()">${IC.plus} ${t("salesCreateTask")}</button></div>`:"";
  
  let contentHtml = "";
  if(mine.length) {
    contentHtml = `<div class="task-cards">${mine.map(x=>`<div class="tcard card pl-${x.priority}"><div class="thead"><span class="tid">${x.task_id}</span>${statBadge(x.status)}</div><div class="cust">${esc(x.customer_name)}</div><div class="desc">${esc(x.description)}</div><div class="meta">${prioBadge(x.priority)}<span class="badge b-waiting">${esc(x.department)}</span></div>${x.status==="in_progress"?`<textarea id="fb_${x.task_id}" rows="2" placeholder="${t("feedbackPlaceholder")}"></textarea>`:""}<div class="foot">${x.status==="waiting"||x.status==="delayed"?`<button class="btn btn-primary btn-sm" onclick="changeStatus('${x.task_id}','in_progress')">${IC.play} ${t("start")}</button>`:""}${x.status==="in_progress"?`<button class="btn btn-success btn-sm" onclick="completeWithFeedback('${x.task_id}')">${IC.check} ${t("completeWithFeedback")}</button>`:""}<button class="btn btn-outline btn-sm" onclick="openTaskDetails('${x.task_id}')">${t("details")}</button></div></div>`).join("")}</div>`;
  } else {
    // Only show "No Tasks Today" if we are NOT a sales employee, because Sales employee has the follow-ups section right below and we don't want a huge empty box if they have no assigned tasks.
    if(!isSalesEmp()) {
      contentHtml = `<div class="card empty">${t("noTasksToday")}</div>`;
    }
  }

  return heroHtml + salesCreateHtml + contentHtml + followupHtml;
}
async function completeWithFeedback(tid){const x=TASKS.find(x=>x.task_id===tid),fb=$(`#fb_${tid}`)?.value.trim()||"";const upd={status:"completed",completed_at:nowISO(),updated_at:nowISO(),feedback:fb};if(fb)upd.notes=(x.notes||"")+"\n\n"+t("feedback")+": "+fb;const r=await sb.from("tasks").update(upd).eq("task_id",tid);if(r.error)return toast(r.error.message,"e");Object.assign(x,upd);await addHistory(tid,"actCompleted",fb);if(fb)await sb.from("notifications").insert({emp_id:null,title:t("empFeedback").replace("{emp}",empName(session.empId)).replace("{tid}",tid)+": "+fb});toast(fb?t("feedbackSent"):t("taskCompleted"),"s");rerenderCurrent()}
window.setFollowupFilterDate = function(v){followupFilterDate=v||todayStr();renderContent();}
window.openAddFollowupModal = function(){
  openModal(`<h3>${IC.plus} ${t("addFollowup")}<button class="x" onclick="closeModal()">${IC.xmark}</button></h3>
  <div style="display:grid;gap:14px">
    <div><label>${t("customer")} *</label><input id="fcCust" autofocus></div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">
      <div><label>${t("phone")}</label><input id="fcPhone" type="tel" style="direction:ltr;text-align:left" placeholder="+20 ..."></div>
      <div><label>${t("email")}</label><input id="fcEmailInput" type="email" style="direction:ltr;text-align:left" placeholder="example@company.com"></div>
    </div>
    <div style="display:flex;gap:24px;margin-top:6px">
      <label style="display:flex;align-items:center;gap:8px;cursor:pointer"><input type="checkbox" id="fcCall" style="width:auto"> ${t("callDone")}</label>
      <label style="display:flex;align-items:center;gap:8px;cursor:pointer"><input type="checkbox" id="fcEmailSent" style="width:auto"> ${t("emailSentF")}</label>
    </div>
    <div><label>${t("followupResult")} *</label><select id="fcResult"><option value="positive">🟢 ${t("fr_positive")}</option><option value="followup" selected>🟡 ${t("fr_followup")}</option><option value="negative">🔴 ${t("fr_negative")}</option><option value="no_answer">⚫ ${t("fr_no_answer")}</option></select></div>
    <button class="btn btn-primary" onclick="saveClientFollowup()">${t("save")}</button>
  </div>`,520);
  setTimeout(()=>$("#fcCust")?.focus(),60);
}
window.saveClientFollowup = async function(){
  const cust=$("#fcCust").value.trim();if(!cust){toast(t("fillRequired"),"w");return}
  const phone=$("#fcPhone")?.value.trim()||"", email=$("#fcEmailInput")?.value.trim()||"";
  const call_done=$("#fcCall").checked,email_sent=$("#fcEmailSent").checked,result=$("#fcResult").value;
  const me=empById(session.empId);
  const base={employee_id:session.empId,employee_name:me.name,customer_name:cust,call_done,email_sent};
  const full={...base,phone,email,result};

  let{data,error}=await sb.from("sales_followups").insert(full).select().single();

  // Fallback: if some columns don't exist yet in Supabase, retry with fewer fields
  if(error && /column|schema cache/i.test(error.message||"")){
    const noPhoneEmail={...base,result};
    let r2=await sb.from("sales_followups").insert(noPhoneEmail).select().single();
    if(r2.error && /column|schema cache/i.test(r2.error.message||"")){
      let r3=await sb.from("sales_followups").insert(base).select().single();
      data=r3.data;error=r3.error;
      if(!error) toast(LANG==="ar"?"تم الحفظ — شغّل أمر SQL لإضافة الأعمدة الناقصة":"Saved — run the SQL to add missing columns","w");
    } else {
      data=r2.data;error=r2.error;
      if(!error) toast(LANG==="ar"?"تم الحفظ — شغّل أمر SQL لإضافة عمودي الرقم والإيميل":"Saved — run the SQL to add phone/email columns","w");
    }
  }

  if(error){
    if(/row-level security|policy/i.test(error.message||"")){
      toast(LANG==="ar"?"صلاحيات الجدول مقفولة — شغّل أمر RLS في Supabase":"RLS blocked — run the RLS SQL in Supabase","e");
      console.error("RLS ERROR:",error.message);
    } else {
      toast(error.message,"e");
    }
    return;
  }
  FOLLOWUPS_CACHE.unshift(data);closeModal();
  toast(t("followupSaved"),"s");
  renderContent();
}

function salesCreateTaskModal(){const opts=EMPLOYEES.filter(e=>e.id!==session.empId).map(e=>`<option value="${e.id}">${esc(e.name)} — ${esc(e.department)}</option>`).join("");openModal(`<h3>${t("salesCreateTask")}<button class="x" onclick="closeModal()">${IC.xmark}</button></h3><div style="display:grid;gap:14px"><label>${t("customer")}</label><input id="sCust"><label>${t("assignTo")}</label><select id="sEmp">${opts}</select><label>${t("description")}</label><textarea id="sDesc" rows="3"></textarea><label>${t("notes")}</label><textarea id="sNotes" rows="2"></textarea><button class="btn btn-primary" onclick="saveSalesTask()">${t("create")}</button></div>`,500)}
async function saveSalesTask(){const me=empById(session.empId),emp=$("#sEmp").value,target=empById(emp),desc=$("#sDesc").value.trim();if(!desc)return toast(t("fillRequired"),"w");const tid=await nextTaskId(),task={task_id:tid,customer_name:$("#sCust").value.trim()||"—",department:target.department,employee_id:emp,description:desc,quantity:1,priority:"medium",status:"waiting",notes:$("#sNotes").value.trim(),due_date:todayStr(),created_by:me.name};const r=await sb.from("tasks").insert(task);if(r.error)return toast(r.error.message,"e");TASKS.unshift({...task,created_at:nowISO(),archived:false});await sb.from("notifications").insert({emp_id:null,title:t("empCreatedTask").replace("{emp}",me.name).replace("{tid}",tid).replace("{target}",target.name)});closeModal();toast(t("taskCreated"),"s");rerenderCurrent()}

function getWeekRange(d=new Date()){const day=d.getDay(),diff=d.getDate()-day+(day===0?-6:1),mon=new Date(d);mon.setDate(diff);mon.setHours(0,0,0,0);const sun=new Date(mon);sun.setDate(mon.getDate()+6);return{start:todayStr(mon),end:todayStr(sun)}}
async function loadSalesReports(){const r=await sb.from("sales_reports").select("*").order("created_at",{ascending:false});SR_CACHE=r.data||[]}async function loadSalesClients(report_id){const r=await sb.from("sales_report_clients").select("*").eq("report_id",report_id).order("created_at");SR_CLIENTS_CACHE=r.data||[]}
async function saveReportNotes(reportId){const notes=$("#srGeneralNotes").value.trim();const r=await sb.from("sales_reports").update({notes}).eq("id",reportId);if(r.error)return toast(r.error.message,"e");const rep=SR_CACHE.find(x=>x.id===reportId);if(rep)rep.notes=notes;toast(t("dataSaved"),"s")}
async function exportAdminReportPdf(id){const r=SR_CACHE.find(x=>x.id===id);if(!r)return;await loadSalesClients(id);const m=salesModeFromRange(r),title=m==="daily"?t("dailySalesReport"):m==="monthly"?t("monthlySalesReport"):t("weeklySalesReport"),el=$("#printArea");el.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #1B3A5C;padding-bottom:10px;margin-bottom:16px"><div style="display:flex;align-items:center;gap:10px"><img src="${LOGO_URL}" style="width:50px;height:50px" crossorigin="anonymous"><div><h2 style="margin:0;font-size:20px;color:#1B3A5C">${esc(SETTINGS.company)}</h2><div style="font-size:12px;color:#666">${esc(SETTINGS.companyAr)}</div></div></div><div style="text-align:end"><div style="font-size:16px;font-weight:800;color:#1B3A5C">${title}</div><div style="font-size:13px;color:#666">${esc(r.employee_name)} • ${fmtDate(r.week_start)} → ${fmtDate(r.week_end)}</div></div></div><table style="width:100%;border-collapse:collapse;margin-bottom:14px"><thead><tr>${[t("companyNameF"),t("contactPerson"),t("phone"),t("callStatus"),t("emailStatus"),t("interested"),t("visit"),t("notes")].map(h=>`<th style="border:1px solid #bbb;padding:7px 9px;font-size:12px;background:#F0EDE4;text-align:start;color:#1B3A5C">${h}</th>`).join("")}</tr></thead><tbody>${SR_CLIENTS_CACHE.map(c=>`<tr><td style="border:1px solid #bbb;padding:6px 9px;font-size:12px;font-weight:bold">${esc(c.company_name)}</td><td style="border:1px solid #bbb;padding:6px 9px;font-size:12px">${esc(c.contact_person||"—")}</td><td style="border:1px solid #bbb;padding:6px 9px;font-size:12px">${esc(c.phone||"—")}</td><td style="border:1px solid #bbb;padding:6px 9px;font-size:12px">${t(c.call_status||"notCalled")}</td><td style="border:1px solid #bbb;padding:6px 9px;font-size:12px">${t(c.email_status||"notSent")}</td><td style="border:1px solid #bbb;padding:6px 9px;font-size:12px">${c.interested?t("yes"):t("no")}</td><td style="border:1px solid #bbb;padding:6px 9px;font-size:12px">${c.visit_date?fmtDate(c.visit_date):"—"}</td><td style="border:1px solid #bbb;padding:6px 9px;font-size:12px;color:#555">${esc(c.notes||"")}</td></tr>`).join("")||`<tr><td colspan="8" style="text-align:center;padding:12px">${t("noResults")}</td></tr>`}</tbody></table>${r.notes?`<div style="margin-top:14px;border:1px solid #bbb;border-radius:8px;padding:12px;background:#FAFAF5"><b style="display:block;margin-bottom:6px;color:#1B3A5C">${t("notes")}:</b><div style="font-size:13px;white-space:pre-wrap">${esc(r.notes)}</div></div>`:""}<div style="display:flex;justify-content:space-between;margin-top:36px;font-size:13px"><div style="width:200px;border-top:1.5px solid #333;padding-top:6px;text-align:center">${t("supervisor")} — ${t("signature")}</div><div style="width:200px;border-top:1.5px solid #333;padding-top:6px;text-align:center">${t("signature")}</div></div><div style="margin-top:18px;text-align:center;font-size:11px;color:#888;border-top:1px solid #ddd;padding-top:8px">${t("generatedBy")} — ${new Date().toLocaleString()}</div>`;toast(t("downloading"),"i");el.style.display="block";el.style.position="fixed";el.style.left="-9999px";el.style.top="0";el.style.width="210mm";el.style.padding="14mm";el.style.background="#fff";el.style.color="#111";el.style.direction=LANG==="ar"?"rtl":"ltr";const imgs=el.querySelectorAll("img");await Promise.all([...imgs].map(img=>img.complete?Promise.resolve():new Promise(r=>{img.onload=r;img.onerror=r;})));await new Promise(r=>setTimeout(r,300));try{const canvas=await html2canvas(el,{scale:2,useCORS:true,allowTaint:true,backgroundColor:"#ffffff",logging:false});const imgData=canvas.toDataURL("image/jpeg",0.92),{jsPDF}=window.jspdf,pdf=new jsPDF({orientation:"portrait",unit:"mm",format:"a4"});const pW=pdf.internal.pageSize.getWidth(),pH=pdf.internal.pageSize.getHeight(),imgW=pW,imgH=(canvas.height*pW)/canvas.width;let pos=0;pdf.addImage(imgData,"JPEG",0,pos,imgW,imgH);let remaining=imgH-pH;while(remaining>0){pdf.addPage();pos-=pH;pdf.addImage(imgData,"JPEG",0,pos,imgW,imgH);remaining-=pH}pdf.save("kaizen-sales-"+r.employee_name+"-"+r.week_start+".pdf");toast(t("downloadPdf")+" ✓","s")}catch(err){console.error("PDF error:",err);toast("PDF error","e")}el.style.display="none";el.style.position="";el.style.left=""}
async function getOrCreateCurrentReport(){await loadSalesReports();const me=empById(session.empId),wk=getWeekRange();let rep=SR_CACHE.find(r=>r.employee_id===session.empId&&r.week_start===wk.start);if(!rep){const r=await sb.from("sales_reports").insert({employee_id:session.empId,employee_name:me.name,department:me.department,week_start:wk.start,week_end:wk.end,submitted:false}).select().single();if(r.error){toast(r.error.message,"e");return null}rep=r.data;SR_CACHE.unshift(rep)}await loadSalesClients(rep.id);return rep}
function srStats(c){return{total:c.length,calls:c.filter(x=>x.call_status&&x.call_status!=="notCalled").length,emails:c.filter(x=>x.email_status==="sent").length,interested:c.filter(x=>x.interested).length,visits:c.filter(x=>x.visit_date).length}}
async function viewSalesReport(){const rep=await getOrCreateCurrentReport();if(!rep)return`<div class="empty">Run sales report SQL first.</div>`;const s=srStats(SR_CLIENTS_CACHE),ro=rep.submitted;return`<h1 class="page-title">${t("weeklySalesReport")}</h1><div class="page-sub">${esc(empName(session.empId))} — ${t("weekStart")}: ${fmtDate(rep.week_start)} → ${t("weekEnd")}: ${fmtDate(rep.week_end)} ${ro?`<span class="badge b-completed">✓ ${t("reportSubmitted")}</span>`:""}</div><div class="grid stats-grid" style="grid-template-columns:repeat(5,1fr)">${[["totalClients",s.total],["callsCompleted",s.calls],["emailsSent",s.emails],["interestedClients",s.interested],["scheduledVisits",s.visits]].map(([k,v])=>`<div class="stat-card card"><div class="label">${t(k)}</div><div class="num">${v}</div></div>`).join("")}</div>${ro?`<div class="card" style="padding:16px;margin-bottom:18px"><b style="color:#15803D">${t("reportReadOnly")}</b></div>`:`<button class="btn btn-primary btn-sm" style="margin-bottom:18px" onclick="addSalesClient('${rep.id}')">${IC.plus} ${t("addClient")}</button>`}<div class="card table-wrap"><table style="min-width:1000px"><thead><tr>${["companyNameF","contactPerson","phone","email","callStatus","emailStatus","interested","visit","notes","actions"].map(k=>`<th>${t(k)}</th>`).join("")}</tr></thead><tbody>${SR_CLIENTS_CACHE.map(c=>`<tr><td><b>${esc(c.company_name)}</b></td><td>${esc(c.contact_person||"")}</td><td>${esc(c.phone||"")}</td><td>${esc(c.email||"")}</td><td>${t(c.call_status||"notCalled")}</td><td>${t(c.email_status||"notSent")}</td><td>${c.interested?"✓":"—"}</td><td>${c.visit_date?fmtDate(c.visit_date):"—"}</td><td style="max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.notes||"")}</td><td>${ro?`<button class="act" onclick="viewSalesClient('${c.id}')">${IC.eye}</button>`:`<button class="act" onclick="editSalesClient('${c.id}','${rep.id}')">${IC.edit}</button><button class="act" onclick="deleteSalesClient('${c.id}')">${IC.trash}</button>`}</td></tr>`).join("")||`<tr><td colspan="10"><div class="empty">${t("noResults")}</div></td></tr>`}</tbody></table></div>${!ro?`<div style="text-align:center;margin-top:22px"><button class="btn btn-success" onclick="submitSalesReport('${rep.id}')">${IC.check} ${t("submitReport")}</button></div>`:""}`}
function addSalesClient(report_id){openModal(`<h3>${t("addClient")}<button class="x" onclick="closeModal()">${IC.xmark}</button></h3><div style="display:grid;gap:14px"><label>${t("companyNameF")} *</label><input id="scName"><label>${t("contactPerson")}</label><input id="scContact"><label>${t("phone")}</label><input id="scPhone"><label>${t("email")}</label><input id="scEmail"><button class="btn btn-primary" onclick="saveSalesClient('${report_id}')">${t("save")}</button></div>`,480)}
async function saveSalesClient(report_id){const company_name=$("#scName").value.trim();if(!company_name)return toast(t("fillRequired"),"w");const r=await sb.from("sales_report_clients").insert({report_id,company_name,contact_person:$("#scContact").value.trim(),phone:$("#scPhone").value.trim(),email:$("#scEmail").value.trim(),call_status:"notCalled",email_status:"notSent"}).select().single();if(r.error)return toast(r.error.message,"e");SR_CLIENTS_CACHE.push(r.data);closeModal();toast(t("clientSaved"),"s");renderContent()}
function editSalesClient(id){const c=SR_CLIENTS_CACHE.find(x=>x.id===id);if(!c)return;openModal(`<h3>${t("editClient")}<button class="x" onclick="closeModal()">${IC.xmark}</button></h3><div style="display:grid;gap:14px"><label>${t("companyNameF")}</label><input id="ecName" value="${esc(c.company_name)}"><label>${t("callStatus")}</label><select id="ecCall">${CALL_STATUSES.map(s=>`<option value="${s}" ${s===c.call_status?"selected":""}>${t(s)}</option>`).join("")}</select><label>${t("emailStatus")}</label><select id="ecEmailSt">${EMAIL_STATUSES.map(s=>`<option value="${s}" ${s===c.email_status?"selected":""}>${t(s)}</option>`).join("")}</select><label><input type="checkbox" id="ecInterested" ${c.interested?"checked":""} style="width:auto;margin-inline-end:8px" onchange="toggleVisitFields()"> ${t("interested")}</label><div id="visitFields" style="display:${c.interested?"grid":"none"};gap:14px"><label>${t("visitDate")}</label><input id="ecVisitDate" type="date" value="${c.visit_date||""}"><label>${t("visitAddress")}</label><input id="ecVisitAddr" value="${esc(c.visit_address||"")}"><label>${t("requestedSamples")}</label><select id="ecSamples"><option value="no">${t("no")}</option><option value="yes" ${c.requested_samples?"selected":""}>${t("yes")}</option></select><label>${t("requestedPresentation")}</label><select id="ecPres"><option value="no">${t("no")}</option><option value="yes" ${c.requested_presentation?"selected":""}>${t("yes")}</option></select><label>${t("visitNotes")}</label><textarea id="ecVisitNotes">${esc(c.visit_notes||"")}</textarea></div><label>${t("notes")}</label><textarea id="ecNotes" rows="3">${esc(c.notes||"")}</textarea><button class="btn btn-primary" onclick="updateSalesClient('${id}')">${t("save")}</button></div>`,560)}
function toggleVisitFields(){if($("#visitFields"))$("#visitFields").style.display=$("#ecInterested").checked?"grid":"none"}
async function updateSalesClient(id){const interested=$("#ecInterested").checked,upd={company_name:$("#ecName").value.trim()||"—",call_status:$("#ecCall").value,email_status:$("#ecEmailSt").value,interested,notes:$("#ecNotes").value.trim(),visit_date:interested&&$("#ecVisitDate").value?$("#ecVisitDate").value:null,visit_address:interested?$("#ecVisitAddr").value.trim():"",requested_samples:interested&&$("#ecSamples").value==="yes",requested_presentation:interested&&$("#ecPres").value==="yes",visit_notes:interested?$("#ecVisitNotes").value.trim():""};const r=await sb.from("sales_report_clients").update(upd).eq("id",id);if(r.error)return toast(r.error.message,"e");Object.assign(SR_CLIENTS_CACHE.find(x=>x.id===id),upd);closeModal();toast(t("clientSaved"),"s");renderContent()}
function viewSalesClient(id){const c=SR_CLIENTS_CACHE.find(x=>x.id===id);if(c)openModal(`<h3>${t("details")}<button class="x" onclick="closeModal()">${IC.xmark}</button></h3><div class="detail-grid">${Object.entries({companyNameF:c.company_name,contactPerson:c.contact_person,phone:c.phone,email:c.email,callStatus:t(c.call_status||"notCalled"),emailStatus:t(c.email_status||"notSent"),interested:c.interested?t("yes"):t("no"),visit:c.visit_date?fmtDate(c.visit_date):"—",notes:c.notes}).map(([k,v])=>`<div class="dg"><div class="k">${t(k)}</div><div class="v">${esc(v||"—")}</div></div>`).join("")}</div>`,520)}
function deleteSalesClient(id){confirmModal(t("deleteClient")+"?",async()=>{await sb.from("sales_report_clients").delete().eq("id",id);SR_CLIENTS_CACHE=SR_CLIENTS_CACHE.filter(x=>x.id!==id);renderContent()})}
function submitSalesReport(id){confirmModal(t("confirmSubmit"),async()=>{await sb.from("sales_reports").update({submitted:true,submitted_at:nowISO()}).eq("id",id);toast(t("reportSubmitted"),"s");renderContent()},false)}
async function viewAdminSalesReports(){await loadSalesReports();const rows=[];for(const r of SR_CACHE.filter(x=>x.submitted)){const cl=await sb.from("sales_report_clients").select("*").eq("report_id",r.id);const s=srStats(cl.data||[]);rows.push(`<tr><td><b>${esc(r.employee_name)}</b></td><td>${fmtDate(r.week_start)} → ${fmtDate(r.week_end)}</td><td>${s.calls}</td><td>${s.emails}</td><td>${s.interested}</td><td>${s.visits}</td><td>${r.submitted_at?fmtFull(r.submitted_at):"—"}</td><td><button class="btn btn-outline btn-sm" onclick="adminViewReport('${r.id}')">${IC.eye} ${t("viewReport")}</button></td></tr>`)}return`<h1 class="page-title">${t("salesReports")}</h1><div class="card table-wrap"><table><thead><tr><th>${t("employee")}</th><th>${t("week")}</th><th>${t("calls")}</th><th>${t("emails")}</th><th>${t("interested")}</th><th>${t("visits")}</th><th>${t("submissionDate")}</th><th>${t("actions")}</th></tr></thead><tbody>${rows.join("")||`<tr><td colspan="8"><div class="empty">${t("noReports")}</div></td></tr>`}</tbody></table></div>`}
async function adminViewReport(id){const r=SR_CACHE.find(x=>x.id===id);await loadSalesClients(id);openModal(`<h3>${t("weeklySalesReport")} — ${esc(r.employee_name)}<button class="x" onclick="closeModal()">${IC.xmark}</button></h3><div class="page-sub">${fmtDate(r.week_start)} → ${fmtDate(r.week_end)}</div><div class="table-wrap"><table><thead><tr><th>${t("companyNameF")}</th><th>${t("contactPerson")}</th><th>${t("phone")}</th><th>${t("callStatus")}</th><th>${t("emailStatus")}</th><th>${t("interested")}</th><th>${t("visit")}</th><th>${t("notes")}</th></tr></thead><tbody>${SR_CLIENTS_CACHE.map(c=>`<tr><td><b>${esc(c.company_name)}</b></td><td>${esc(c.contact_person||"")}</td><td>${esc(c.phone||"")}</td><td>${t(c.call_status||"notCalled")}</td><td>${t(c.email_status||"notSent")}</td><td>${c.interested?"✓":"—"}</td><td>${c.visit_date?fmtDate(c.visit_date):"—"}</td><td>${esc(c.notes||"")}</td></tr>`).join("")}</tbody></table></div>`,800)}
function downloadDailyPdf(){toast(t("downloading"),"i");window.print()}function downloadReportPdf(){toast(t("downloading"),"i");window.print()}


function netStatus(){const b=$("#offlineBar");if(!navigator.onLine){b.textContent=t("offline")||"Offline";b.classList.add("on")}else b.classList.remove("on")}window.addEventListener("online",netStatus);window.addEventListener("offline",netStatus);

Object.assign(T.ar,{daily:"يومي",monthly:"شهري",dailySalesReport:"تقرير المبيعات اليومي",monthlySalesReport:"تقرير المبيعات الشهري",salesLog:"سجل التقارير",selectDate:"اختار التاريخ",period:"الفترة",open:"فتح",currentReport:"التقرير الحالي",
  clientFollowup:"متابعة العميل",todayFollowups:"العمليات المضافة اليوم",addFollowup:"إضافة متابعة جديدة",callDone:"تمت مكالمة (كول)",emailSentF:"تم إرسال إيميل",followupSaved:"تم حفظ المتابعة",followupLog:"سجل المتابعات اليومية",filterDate:"تاريخ المتابعة",noFollowups:"لا توجد عمليات متابعة لهذا اليوم",followupResult:"نتيجة المتابعة",fr_positive:"مهتم",fr_followup:"محتاج متابعة لاحقًا",fr_negative:"غير مهتم",fr_no_answer:"لم يرد"});
Object.assign(T.en,{daily:"Daily",monthly:"Monthly",dailySalesReport:"Daily Sales Report",monthlySalesReport:"Monthly Sales Report",salesLog:"Reports Log",selectDate:"Select Date",period:"Period",open:"Open",currentReport:"Current Report",
  clientFollowup:"Client Follow-up",todayFollowups:"Today's Follow-ups",addFollowup:"Add New Follow-up",callDone:"Call Done",emailSentF:"Email Sent",followupSaved:"Follow-up saved",followupLog:"Daily Follow-ups Log",filterDate:"Follow-up Date",noFollowups:"No follow-ups for this day",followupResult:"Follow-up Result",fr_positive:"Positive",fr_followup:"Follow Up",fr_negative:"Negative",fr_no_answer:"No Answer"});

function getSalesRange(mode=salesPeriodMode,date=salesPeriodDate){
  const d=new Date(date||todayStr());
  if(mode==="daily")return{start:todayStr(d),end:todayStr(d)};
  if(mode==="monthly"){const s=new Date(d.getFullYear(),d.getMonth(),1),e=new Date(d.getFullYear(),d.getMonth()+1,0);return{start:todayStr(s),end:todayStr(e)}}
  const day=d.getDay(),diff=d.getDate()-day+(day===0?-6:1),mon=new Date(d);mon.setDate(diff);mon.setHours(0,0,0,0);const sun=new Date(mon);sun.setDate(mon.getDate()+6);return{start:todayStr(mon),end:todayStr(sun)};
}
function salesModeFromRange(r){if(r.week_start===r.week_end)return"daily";const s=new Date(r.week_start),e=new Date(r.week_end);if(s.getDate()===1&&e.getDate()===new Date(e.getFullYear(),e.getMonth()+1,0).getDate())return"monthly";return"weekly"}
function salesModeTitle(mode=salesPeriodMode){return mode==="daily"?t("dailySalesReport"):mode==="monthly"?t("monthlySalesReport"):t("weeklySalesReport")}
function setSalesPeriod(mode){salesPeriodMode=mode;renderContent()}
function setSalesPeriodDate(v){salesPeriodDate=v||todayStr();renderContent()}
function openSalesReportPeriod(start,end){salesPeriodMode=start===end?"daily":(new Date(start).getDate()===1&&new Date(end).getDate()===new Date(new Date(end).getFullYear(),new Date(end).getMonth()+1,0).getDate()?"monthly":"weekly");salesPeriodDate=start;renderContent()}

async function getOrCreateCurrentReport(){await loadSalesReports();const me=empById(session.empId),range=getSalesRange();let rep=SR_CACHE.find(r=>r.employee_id===session.empId&&r.week_start===range.start&&r.week_end===range.end);if(!rep){const r=await sb.from("sales_reports").insert({employee_id:session.empId,employee_name:me.name,department:me.department,week_start:range.start,week_end:range.end,submitted:false}).select().single();if(r.error){toast(r.error.message,"e");return null}rep=r.data;SR_CACHE.unshift(rep)}await loadSalesClients(rep.id);return rep}

async function viewSalesReport(){
  const rep=await getOrCreateCurrentReport();if(!rep)return`<div class="empty">Run sales report SQL first.</div>`;
  const s=srStats(SR_CLIENTS_CACHE),ro=rep.submitted,range=getSalesRange();
  const history=SR_CACHE.filter(r=>r.employee_id===session.empId).sort((a,b)=>new Date(b.week_start)-new Date(a.week_start));
  const tabs=[["daily","daily"],["weekly","weeklySalesReport"],["monthly","monthly"]];
  return`<h1 class="page-title">${salesModeTitle()}</h1>
  <div class="page-sub">${esc(empName(session.empId))} — ${t("weekStart")}: ${fmtDate(rep.week_start)} → ${t("weekEnd")}: ${fmtDate(rep.week_end)} ${ro?`<span class="badge b-completed">✓ ${t("reportSubmitted")}</span>`:""}</div>
  <div class="card" style="padding:16px;margin-bottom:18px;display:flex;align-items:end;gap:12px;flex-wrap:wrap">
    <div class="seg">${tabs.map(([m,l])=>`<button class="${salesPeriodMode===m?"on":""}" onclick="setSalesPeriod('${m}')">${m==="weekly"?t("weeklySalesReport"):t(l)}</button>`).join("")}</div>
    <div style="min-width:210px"><label>${t("selectDate")}</label><input type="date" value="${salesPeriodDate}" onchange="setSalesPeriodDate(this.value)"></div>
    <div style="color:var(--muted);font-size:13px;padding-bottom:10px">${t("period")}: ${fmtDate(range.start)} → ${fmtDate(range.end)}</div>
  </div>
  <div class="grid stats-grid" style="grid-template-columns:repeat(5,1fr)">${[["totalClients",s.total],["callsCompleted",s.calls],["emailsSent",s.emails],["interestedClients",s.interested],["scheduledVisits",s.visits]].map(([k,v])=>`<div class="stat-card card"><div class="label">${t(k)}</div><div class="num">${v}</div></div>`).join("")}</div>
  ${ro?`<div class="card" style="padding:16px;margin-bottom:18px"><b style="color:#15803D">${t("reportReadOnly")}</b></div>`:`<button class="btn btn-primary btn-sm" style="margin-bottom:18px" onclick="addSalesClient('${rep.id}')">${IC.plus} ${t("addClient")}</button>`}
  <div class="card table-wrap"><table style="min-width:1000px"><thead><tr>${["companyNameF","contactPerson","phone","email","callStatus","emailStatus","interested","visit","notes","actions"].map(k=>`<th>${t(k)}</th>`).join("")}</tr></thead><tbody>${SR_CLIENTS_CACHE.map(c=>`<tr><td><b>${esc(c.company_name)}</b></td><td>${esc(c.contact_person||"")}</td><td>${esc(c.phone||"")}</td><td>${esc(c.email||"")}</td><td>${t(c.call_status||"notCalled")}</td><td>${t(c.email_status||"notSent")}</td><td>${c.interested?"✓":"—"}</td><td>${c.visit_date?fmtDate(c.visit_date):"—"}</td><td style="max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.notes||"")}</td><td>${ro?`<button class="act" onclick="viewSalesClient('${c.id}')">${IC.eye}</button>`:`<button class="act" onclick="editSalesClient('${c.id}','${rep.id}')">${IC.edit}</button><button class="act" onclick="deleteSalesClient('${c.id}')">${IC.trash}</button>`}</td></tr>`).join("")||`<tr><td colspan="10"><div class="empty">${t("noResults")}</div></td></tr>`}</tbody></table></div>
  <div class="card" style="padding:18px;margin-top:18px"><label>${t("notes")}</label><textarea id="srGeneralNotes" rows="3" placeholder="${t("notes")}..." ${ro?"readonly":""}>${esc(rep.notes||"")}</textarea>${!ro?`<button class="btn btn-primary btn-sm" style="margin-top:10px" onclick="saveReportNotes('${rep.id}')">${t("save")}</button>`:""}</div>
  ${!ro?`<div style="text-align:center;margin-top:22px"><button class="btn btn-success" onclick="submitSalesReport('${rep.id}')">${IC.check} ${t("submitReport")}</button></div>`:""}
  <div style="margin-top:28px"><h2 style="font-size:20px;font-weight:800;margin-bottom:12px">${t("salesLog")}</h2><div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(240px,1fr))">${history.map(r=>{const m=salesModeFromRange(r);return`<button class="card" style="padding:16px;text-align:start" onclick="openSalesReportPeriod('${r.week_start}','${r.week_end}')"><b>${m==="daily"?t("daily"):m==="monthly"?t("monthly"):t("weeklySalesReport")}</b><div style="color:var(--muted);font-size:13px;margin-top:5px">${fmtDate(r.week_start)} → ${fmtDate(r.week_end)}</div><div style="margin-top:8px">${r.submitted?`<span class="badge b-completed">✓ ${t("reportSubmitted")}</span>`:`<span class="badge b-delayed">${t("inProgress")}</span>`}</div></button>`}).join("")||`<div class="empty card">${t("noReports")}</div>`}</div></div>`;
}

async function viewAdminSalesReports(){await loadSalesReports();const rows=[];for(const r of SR_CACHE.filter(x=>x.submitted)){const cl=await sb.from("sales_report_clients").select("*").eq("report_id",r.id);const s=srStats(cl.data||[]),m=salesModeFromRange(r);rows.push(`<tr><td><b>${esc(r.employee_name)}</b></td><td><span class="badge b-waiting">${m==="daily"?t("daily"):m==="monthly"?t("monthly"):t("weeklySalesReport")}</span></td><td>${fmtDate(r.week_start)} → ${fmtDate(r.week_end)}</td><td>${s.calls}</td><td>${s.emails}</td><td>${s.interested}</td><td>${s.visits}</td><td>${r.submitted_at?fmtFull(r.submitted_at):"—"}</td><td><button class="btn btn-outline btn-sm" onclick="adminViewReport('${r.id}')">${IC.eye} ${t("viewReport")}</button></td></tr>`)}return`<h1 class="page-title">${t("salesReports")}</h1><div class="card table-wrap"><table><thead><tr><th>${t("employee")}</th><th>${t("period")}</th><th>${t("week")}</th><th>${t("calls")}</th><th>${t("emails")}</th><th>${t("interested")}</th><th>${t("visits")}</th><th>${t("submissionDate")}</th><th>${t("actions")}</th></tr></thead><tbody>${rows.join("")||`<tr><td colspan="9"><div class="empty">${t("noReports")}</div></td></tr>`}</tbody></table></div>`}

async function adminViewReport(id){const r=SR_CACHE.find(x=>x.id===id);await loadSalesClients(id);const m=salesModeFromRange(r);openModal(`<h3>${m==="daily"?t("dailySalesReport"):m==="monthly"?t("monthlySalesReport"):t("weeklySalesReport")} — ${esc(r.employee_name)}<button class="x" onclick="closeModal()">${IC.xmark}</button></h3><div class="page-sub">${fmtDate(r.week_start)} → ${fmtDate(r.week_end)}</div>
  <div style="display:flex;gap:10px;margin-bottom:14px"><button class="btn btn-outline btn-sm" onclick="exportAdminReportPdf('${r.id}')">${IC.archive} ${t("downloadPdf")}</button></div>
  <div class="table-wrap"><table><thead><tr><th>${t("companyNameF")}</th><th>${t("contactPerson")}</th><th>${t("phone")}</th><th>${t("callStatus")}</th><th>${t("emailStatus")}</th><th>${t("interested")}</th><th>${t("visit")}</th><th>${t("notes")}</th></tr></thead><tbody>${SR_CLIENTS_CACHE.map(c=>`<tr><td><b>${esc(c.company_name)}</b></td><td>${esc(c.contact_person||"")}</td><td>${esc(c.phone||"")}</td><td>${t(c.call_status||"notCalled")}</td><td>${t(c.email_status||"notSent")}</td><td>${c.interested?"✓":"—"}</td><td>${c.visit_date?fmtDate(c.visit_date):"—"}</td><td>${esc(c.notes||"")}</td></tr>`).join("")}</tbody></table></div>
  ${r.notes?`<div style="margin-top:14px;border:1px solid rgba(27,58,92,.1);border-radius:12px;padding:14px;background:rgba(27,58,92,.02)"><b style="display:block;margin-bottom:6px;color:#1B3A5C">${t("notes")}:</b><div style="font-size:13.5px;white-space:pre-wrap">${esc(r.notes)}</div></div>`:""}`,800)}
(async function boot(){netStatus();const ok=await loadAllData();if(ok){setupRealtime();render()}setTimeout(()=>{$("#loader")?.classList.add("hide");setTimeout(()=>$("#loader")?.remove(),500)},700)})();